import {expect as baseExpect} from '@playwright/test'
import {randomUUID} from 'node:crypto'
import {mkdirSync,writeFileSync} from 'node:fs'
import {prepareCrew} from './crew.mjs'
import {expectSuccess,expectDatabaseError} from '../../scripts/staging/assertions.mjs'
import {handoverExport,todayInZone} from '../../lib/domain/handover.mjs'
import {verifySiteMobile} from './site-mobile.mjs'
const expect=baseExpect.configure({timeout:30000})
export async function handoverWorkflow({browser,origin,actors,options={},capture=async()=>{},record=()=>{}}){
 let stage='fixtures',mobileDiagnostics=null,exportDiagnostics=null;const contexts=[],f=await prepareCrew(actors,'SYNTHETIC site handover'),{company,siteId,briefId,version,actionId}=f,zone='America/Toronto',date=todayInZone(zone)
 const rpc=(role,fn,command,p={})=>actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}}).then(expectSuccess)
 const summary=(role,day=date,z=zone)=>actors[role].client.rpc('ts_site_handover',{site:siteId,day,zone:z}).then(expectSuccess)
 const action=()=>actors.OWNER.client.from('ts_actions').select('*').eq('id',actionId).single().then(expectSuccess)
 const update=async(role,state,responsible=actors.WORKER.id)=>{const a=await action();return rpc(role,'ts_command','update_action',{id:actionId,revision:a.revision,state,responsibleId:responsible,controls:a.controls,resolution:'SYNTHETIC handover progress',targetDate:''})}
 const endpoint='/api/sites/'+siteId+'/handover?'+new URLSearchParams({date,timezone:zone}),site='/sites/'+siteId
 async function login(role){const {localOnly,...settings}=options,c=await browser.newContext({viewport:{width:390,height:844},...settings});contexts.push(c);if(localOnly)await c.route('**/*',r=>[origin,actors[role].apiOrigin].includes(new URL(r.request().url()).origin)?r.continue():r.abort());const p=await c.newPage();p.setDefaultTimeout(30000);p.setDefaultNavigationTimeout(90000);await p.goto(origin+'/auth/login');await p.getByLabel('Email',{exact:true}).fill(actors[role].email);await p.getByLabel('Password',{exact:true}).fill(actors[role].password);await p.getByRole('button',{name:'Sign In',exact:true}).click();await p.waitForURL('**/dashboard');return p}
 try{
  const before=expectSuccess(await actors.OWNER.client.from('ts_brief_versions').select('*').eq('brief_id',briefId))
  await rpc('WORKER','ts_brief_command','acknowledge',{id:briefId,version})
  let b=await rpc('SUPERVISOR','ts_brief_command','revise',{id:briefId,revision:version});b=await rpc('SUPERVISOR','ts_brief_command','save',{id:briefId,revision:b.revision,document:{...b.document,briefingNote:'SYNTHETIC revised discussion',attendance:[actors.WORKER.id]}});await rpc('SUPERVISOR','ts_brief_command','record',{id:briefId,revision:b.revision})
  for(const role of ['WORKER','SUPERVISOR']){let c=await rpc(role,'ts_concern_command','create',{id:randomUUID(),siteId,document:{observation:'SYNTHETIC '+role+' concern',location:'Synthetic bay',immediate:'',observedAt:'2026-01-01T00:00:00Z'}});await rpc(role,'ts_concern_command','submit',{id:c.id,revision:c.revision})}
  stage='authoritative-counts';const s=await summary('SUPERVISOR'),w=await summary('WORKER');expect(s.briefs).toHaveLength(2);expect(s.briefs.find(v=>v.version===version).acknowledgements).toHaveLength(1);expect(s.briefs.find(v=>v.version===b.revision).acknowledgements).toHaveLength(0);expect(s.concerns).toHaveLength(2);expect(w.concerns).toHaveLength(1);expect(s.outstanding).toHaveLength(3);expect(w.outstanding).toHaveLength(2)
  const tomorrow=new Date(date+'T12:00:00Z');tomorrow.setUTCDate(tomorrow.getUTCDate()+1);const future=await summary('SUPERVISOR',tomorrow.toISOString().slice(0,10));expect(future.briefs).toHaveLength(0);expect(future.concerns).toHaveLength(0);expect(future.outstanding).toHaveLength(3)
  const spring=await summary('SUPERVISOR','2026-03-08'),fall=await summary('SUPERVISOR','2026-11-01');expect(Date.parse(spring.end)-Date.parse(spring.start)).toBe(23*3600000);expect(Date.parse(fall.end)-Date.parse(fall.start)).toBe(25*3600000)
  stage='assignment-closure-reopening';await update('SUPERVISOR','open',actors.SUPERVISOR.id);expect((await summary('WORKER')).outstanding.find(a=>a.id===actionId).responsible_id).toBe(actors.SUPERVISOR.id);await update('SUPERVISOR','open');await update('WORKER','awaiting_verification');expect((await summary('SUPERVISOR')).outstanding.filter(a=>a.state==='awaiting_verification')).toHaveLength(1)
  await update('SUPERVISOR','closed');expect((await summary('SUPERVISOR')).closures).toHaveLength(1);await update('SUPERVISOR','open');const reopened=await summary('SUPERVISOR');expect(reopened.closures[0].currentState).toBe('open');expect(reopened.outstanding).toHaveLength(3)
  stage='actual-mobile';const sup=await login('SUPERVISOR'),worker=await login('WORKER'),outside=await login('OUTSIDER');await sup.goto(origin+site+'?'+new URLSearchParams({date,timezone:zone}));const panel=sup.locator('.site-handover');await expect(panel.getByRole('heading',{name:'Outstanding now (3)',exact:true})).toBeVisible();await expect(panel.getByRole('status').filter({hasText:'Refreshed'})).toBeVisible();stage='mobile-keyboard';await expect(panel.getByLabel('Handover date',{exact:true})).toBeEditable();await panel.getByLabel('Day timezone',{exact:true}).focus();await sup.keyboard.press('Tab');await expect(panel.getByRole('button',{name:'Show day',exact:true})).toBeFocused();expect(await panel.getByRole('button',{name:'Show day',exact:true}).evaluate(e=>getComputedStyle(e).outlineStyle)).not.toBe('none');stage='mobile-layout';mobileDiagnostics=await sup.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,activeTag:document.activeElement?.tagName,activeType:document.activeElement?.getAttribute('type')}));expect(mobileDiagnostics.scrollWidth<=mobileDiagnostics.width).toBe(true);await capture(sup,'phone-summary');stage='brief-version-display'
  stage='site-shortcuts';await verifySiteMobile(sup)
  await panel.getByText('Briefing versions recorded that day (2)',{exact:true}).click();await expect(panel.getByText('1 of 1 acknowledged this exact version, as of refresh.',{exact:true})).toBeVisible();await expect(panel.getByText('0 of 1 acknowledged this exact version, as of refresh.',{exact:true})).toBeVisible()
  const scroll=await sup.evaluate(()=>scrollY);await panel.getByRole('link',{name:'Brief version '+version+': SYNTHETIC move materials',exact:true}).click();await sup.getByRole('link',{name:'Back to site: '+f.tag,exact:true}).click();await expect(panel.getByLabel('Handover date',{exact:true})).toHaveValue(date);await expect(panel.getByLabel('Day timezone',{exact:true})).toHaveValue(zone);await expect.poll(()=>sup.evaluate(()=>scrollY)).toBeGreaterThan(Math.max(0,scroll-160));await sup.reload();await expect(panel.getByRole('heading',{name:'Outstanding now (3)',exact:true})).toBeVisible()
  stage='failure-retry';await sup.context().route('**/api/sites/'+siteId+'/handover?*',r=>r.abort());await panel.getByRole('button',{name:'Refresh summary',exact:true}).click();await expect(panel.getByRole('button',{name:'Retry handover',exact:true})).toBeVisible();await expect(panel.getByRole('button',{name:'Download handover',exact:true})).toHaveCount(0);await sup.context().unroute('**/api/sites/'+siteId+'/handover?*');await panel.getByRole('button',{name:'Retry handover',exact:true}).click();await expect(panel.getByRole('heading',{name:'Outstanding now (3)',exact:true})).toBeVisible()
  stage='export';await panel.getByLabel('Handover date',{exact:true}).fill('2026-01-01');await expect(panel.getByRole('button',{name:'Download handover',exact:true})).toBeDisabled();await panel.getByLabel('Handover date',{exact:true}).fill(date);const download=sup.waitForEvent('download');await panel.getByRole('button',{name:'Download handover',exact:true}).click();const file=await download;expect(file.suggestedFilename()).toContain('site-handover');const stream=await file.createReadStream(),chunks=[];for await(const c of stream)chunks.push(c);const html=Buffer.concat(chunks).toString('utf8');expect(html).toContain('Verification events on selected day (1)');expect(html).toContain('SYNTHETIC SUPERVISOR concern');expect(html).toContain('Acknowledgements of this exact version');const actual=await(await sup.context().request.get(origin+endpoint)).json();const normalize=h=>h.replace(/<p><strong>Generated at:<\/strong>[^<]*<\/p>/,'');const expectedHtml=handoverExport(actual,origin);exportDiagnostics={linkOrigins:[...new Set([...html.matchAll(/href="([^"]+)"/g)].map(m=>new URL(m[1]).origin))],expectedOrigin:origin,actualLength:normalize(html).length,expectedLength:normalize(expectedHtml).length};expect(normalize(html)).toBe(normalize(expectedHtml))
  await worker.goto(origin+site);await expect(worker.locator('.site-handover').getByRole('heading',{name:'Outstanding now (2)',exact:true})).toBeVisible();const workerExport=await(await worker.context().request.get(origin+endpoint+'&download=1')).text();expect(workerExport).toContain('SYNTHETIC WORKER concern');expect(workerExport).not.toContain('SYNTHETIC SUPERVISOR concern');await capture(worker,'worker-summary')
  stage='access-and-originals';expect((await outside.context().request.get(origin+endpoint)).status()).toBe(404);expect((await outside.context().request.get(origin+endpoint+'&download=1')).status()).toBe(404);expectDatabaseError(await actors.OUTSIDER.client.rpc('ts_site_handover',{site:siteId,day:date,zone}),'TS_not_found')
  await rpc('OWNER','ts_command','member',{userId:actors.WORKER.id,role:'remove'});expect((await worker.context().request.get(origin+endpoint)).status()).toBe(404);expect((await worker.context().request.get(origin+endpoint+'&download=1')).status()).toBe(404);expect((await summary('SUPERVISOR')).outstanding.find(a=>a.id===actionId).needs_reassignment).toBe(true)
  expect(expectSuccess(await actors.OWNER.client.from('ts_brief_versions').select('*').eq('brief_id',briefId).eq('version',version))).toEqual(before);expect(expectSuccess(await actors.OWNER.client.from('ts_brief_acknowledgements').select('*').eq('brief_id',briefId))).toHaveLength(1)
  record('Handover authoritative counts, exact versions, current versus selected day, DST boundaries, assignment/verification/reopening, UI retry/download, role isolation and unchanged brief PASS',f)
 }catch(e){mkdirSync('test-results',{recursive:true});writeFileSync('test-results/handover-stage.json',JSON.stringify({stage,name:e.name,assertion:e.matcherResult?.name||null,mobileDiagnostics,exportDiagnostics}));throw e}finally{for(const c of contexts)await c.close()}
}
